---level11 script---local isPlayingDemo = falselocal countFail = 0local isSkip = truelocal hasViewedStory = global.getBool("lvl10_b1")if not hasViewedStory or not game.isRestart() then	repeat		if hasViewedStory then dialog.setSkipEnabled(true) end				game.setUserInputEnabled(false)		role.setIdleActionEnabled(false)		script.delay(1)		dialog.show("~~~~~~", faceWeixiao)		camera.setFollowRoleMode(false)		camera.gotoPosition(280,707)		sound.play("51-1")		if dialog.showMinTime("Level10-1", faceBujie,0) ==1 then break end		dialog.show("Level10-2", faceZhoumei)		camera.gotoRole()		camera.setFollowRoleMode(true)				--set story viewed flag        global.setBool("lvl10_b1")		game.restartTiming()		game.setUserInputEnabled(true)		role.setIdleActionEnabled(true)		isPlayingDemo = false			isSkip = false	until trueendif isSkip then	camera.gotoRole()	camera.setFollowRoleMode(true)	dialog.setSkipEnabled(false)	game.resumeLogic()	game.showTutorialDiagram(0)	game.setUserInputEnabled(true)	role.setIdleActionEnabled(true)	game.restartTiming()end